import{_ as t,o as i,c as a,a2 as d}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"CC Switch 添加 CCWS Provider","description":"在 CC Switch 的 Codex 配置中添加 CCWS Provider，填写官网、API 请求地址和 API Key 后启用。","frontmatter":{"title":"CC Switch 添加 CCWS Provider","description":"在 CC Switch 的 Codex 配置中添加 CCWS Provider，填写官网、API 请求地址和 API Key 后启用。"},"headers":[],"relativePath":"guide/cc-switch-provider.md","filePath":"guide/cc-switch-provider.md","lastUpdated":1783061751000}'),r={name:"guide/cc-switch-provider.md"};function o(c,e,l,h,C,s){return i(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="cc-switch-添加-ccws-provider" tabindex="-1">CC Switch 添加 CCWS Provider <a class="header-anchor" href="#cc-switch-添加-ccws-provider" aria-label="Permalink to &quot;CC Switch 添加 CCWS Provider&quot;">​</a></h1><p>如果你希望用 CC Switch 管理 Codex 配置，可以在 Codex 配置里添加一个 CCWS Provider。添加后，Codex 会通过 CCWS 的请求地址和 API Key 发起请求。</p><h2 id="填写字段" tabindex="-1">填写字段 <a class="header-anchor" href="#填写字段" aria-label="Permalink to &quot;填写字段&quot;">​</a></h2><p>在 CC Switch 的自定义 Provider 表单中填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写内容</th></tr></thead><tbody><tr><td>供应商名称</td><td><code>CCWS</code></td></tr><tr><td>官网链接</td><td><code>https://www.ccws.pro</code></td></tr><tr><td>API 请求地址</td><td><code>https://www.ccws.pro/v1</code></td></tr><tr><td>API Key</td><td>当前 CCWS 账号创建的有效 Key</td></tr></tbody></table><p>「完整 URL」开关通常保持默认关闭。除非工作人员特别说明，否则不要把 Base URL 改成完整接口路径。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>打开 CC Switch。</li><li>进入 Codex 配置。</li><li>点击添加 Provider。</li><li>选择自定义配置。</li><li>按上表填写 CCWS 信息。</li><li>保存后启用 <code>CCWS</code> Provider。</li><li>关闭当前终端或 Codex 客户端，然后重新打开。</li></ol><p>如果你还没有安装 CC Switch，请先看 <a href="/guide/config-switch">CC Switch 使用教程</a>。</p><h2 id="启用后验证" tabindex="-1">启用后验证 <a class="header-anchor" href="#启用后验证" aria-label="Permalink to &quot;启用后验证&quot;">​</a></h2><p>打开 Codex，发送一个不修改文件的测试任务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请用一句话说明你已经可以正常回复。</span></span></code></pre></div><p>如果可以正常回复，说明 CC Switch 已经把 CCWS 配置写入 Codex。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li>找不到新增配置：确认是在 CC Switch 的 Codex 应用配置里添加，而不是其他工具配置里添加。</li><li>启用后仍然请求失败：重启 Codex 或重新打开终端。</li><li>提示 401：检查 API Key 是否复制完整，或回到控制台重新生成 Key。</li><li>提示模型不存在：检查 Codex 当前模型名称是否在 CCWS 当前支持范围内。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/guide/codex-base-url">Codex Base URL 怎么填</a></li><li><a href="/guide/codex-api-key">Codex API Key 配置</a></li><li><a href="/guide/codex">Codex 配置</a></li><li><a href="/troubleshooting/codex-error-401-403-429">401 / 403 / 429 排查</a></li></ul>',17)])])}const u=t(r,[["render",o]]);export{p as __pageData,u as default};
